let logoBase64 = '';
let logoMime = 'image/png';

try {
    const logoBuffer = fs.readFileSync(logoPath);
    logoBase64 = logoBuffer.toString('base64');
    if (logoPath.endsWith('.jpeg') || logoPath.endsWith('.jpg')) logoMime = 'image/jpeg';
} catch (e) {
    // Logo fallback silencioso
}

return [{
    json: {
        ...item,
        productoBase64: buffer.toString('base64'),
        productoMime: items[0].binary.data.mimeType || 'image/jpeg',
        logoBase64: logoBase64,
        logoMime: logoMime
    }
}];

const items = $input.all();

return items.map(item => {
    const data = item.json;

    const actualCup = data.cupPrice || data["ACTUAL CUP"] || 0;
    const actualUsd = data.usdPrice || data["ACTUAL USD"] || 0;
    const maxUsd = data["MAX HIST USD"] || actualUsd;

    const numCupPrice = Number(actualCup);

    if (numCupPrice > 45000 && data.html) {

        const usdPrice = actualUsd > 0 ? '$' + Number(actualUsd).toFixed(2) + ' USD' : '0 USD';
        const isUsdDiscount = (maxUsd > actualUsd);

        let newFooterHtml = '';
        let cleanHtml = data.html;

        if (isUsdDiscount) {
            const diffUsdVal = maxUsd - actualUsd;
            const oldUsdStr = '$' + Number(maxUsd).toFixed(2) + ' USD';
            const diffUsdStr = '$' + Number(diffUsdVal).toFixed(2) + ' USD';

            newFooterHtml = `
            <div class="price-container" style="justify-content: center; align-items: baseline; gap: 20px;">
                <span class="old-price" style="font-size: 38px; color: #A0A0A0; text-decoration: line-through;">${oldUsdStr}</span>
                <span class="price-val" style="font-size: 75px; color: #e87b04;">${usdPrice}</span>
            </div>`;

            cleanHtml = cleanHtml.replace(/<div class="price-container">[\s\S]*?<\/div>/, newFooterHtml);

            const newBannerHtml = `
            <div class="discount-banner">
                <span class="banner-title">AHORRAS</span>
                <span class="banner-amounts">${diffUsdStr}</span>
            </div>`;
            cleanHtml = cleanHtml.replace(/<div class="discount-banner">[\s\S]*?<\/div>/, newBannerHtml);

        } else {
            newFooterHtml = `
            <div class="price-container" style="justify-content: center;">
                <span class="price-val" style="font-size: 80px; color: #e87b04;">${usdPrice}</span>
            </div>`;

            cleanHtml = cleanHtml.replace(/<div class="price-container">[\s\S]*?<\/div>/, newFooterHtml);
            cleanHtml = cleanHtml.replace(/<div class="discount-banner">[\s\S]*?<\/div>/, '');
        }

        data.html = cleanHtml;
    }

    return { json: data };
});

